Approach ACK

> I'm not sure if m_callback is actually necessary. Maybe the callback pointer could be derived from m_owner with a cast.

I think I'd prefer this done here. It took me a couple of reads to understand why this is done at all. How about:

```diff
diff --git a/src/util/btcsignals.h b/src/util/btcsignals.h
index 367fcfe851d..74f455fd6f1 100644
--- a/src/util/btcsignals.h
+++ b/src/util/btcsignals.h
@@ -187 +186,0 @@ class signal
-            m_callback = owner.get();
@@ -193,5 +192,5 @@ class signal
-        std::shared_ptr<const void> owner() const { return m_owner.load(); }
-
-        //! Raw pointer to the callback, only valid while holding a shared_ptr
-        //! returned by owner().
-        const function_type* m_callback;
+        std::shared_ptr<const function_type> owner() const
+        {
+            auto owner = m_owner.load();
+            return std::static_pointer_cast<const function_type>(std::move(owner));
+        }
@@ -249 +248 @@ public:
-                    (*connection->m_callback)(args...);
+                    (*owner)(args...);
@@ -260 +259 @@ public:
-                    ret |= (*connection->m_callback)(args...);
+                    ret |= (*owner)(args...);
```

