+        auto state0{std::make_shared<int>(0)};
+        weak0 = state0;
+        sig0.connect([state0 = std::move(state0)] {});
+        BOOST_CHECK(!weak0.expired());
+    }
+    BOOST_CHECK(weak0.expired());
